/**
 * @summary List pets for a creche
 */
export const getListPetsUrl = (crecheId: number, params?: ListPetsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/creches/${crecheId}/pets?${stringifiedParams}`
    : `/api/creches/${crecheId}/pets`;
};

export const listPets = async (
  crecheId: number,
  params?: ListPetsParams,
  options?: RequestInit,
): Promise<Pet[]> => {
  return customFetch<Pet[]>(getListPetsUrl(crecheId, params), {
    ...options,
    method: "GET",
  });
};

export const getListPetsQueryKey = (
  crecheId: number,
  params?: ListPetsParams,
) => {
  return [
    `/api/creches/${crecheId}/pets`,
    ...(params ? [params] : []),
  ] as const;
};

export const getListPetsQueryOptions = <
  TData = Awaited<ReturnType<typeof listPets>>,
  TError = ErrorType<unknown>,
>(
  crecheId: number,
  params?: ListPetsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listPets>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListPetsQueryKey(crecheId, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listPets>>> = ({
    signal,
  }) => listPets(crecheId, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!crecheId,
    ...queryOptions,
  } as UseQueryOptions<Awaited<ReturnType<typeof listPets>>, TError, TData> & {
    queryKey: QueryKey;
  };
};

